arguments.content:
const columns = [
  {
    title: 'Todo',
    tasks: [
      { title: 'Map onboarding flow', assignee: 'Maya Chen', priority: 'High' },
      { title: 'Draft release notes', assignee: 'Noah Patel', priority: 'Medium' },
    ],
  },
  {
    title: 'In Progress',
    tasks: [
      { title: 'Build analytics cards', assignee: 'Ava Brooks', priority: 'High' },
      { title: 'QA mobile navigation', assignee: 'Leo Martin', priority: 'Low' },
    ],
  },
  {
    title: 'Done',
    tasks: [
      { title: 'Set up design tokens', assignee: 'Iris Walker', priority: 'Medium' },
      { title: 'Archive legacy tickets', assignee: 'Sam Rivera', priority: 'Low' },
    ],
  },
]

function TaskCard({ task }) {
  return (
    <article className="task-card">
      <div className="card-topline">
        <span className={`priority priority-${task.priority.toLowerCase()}`}>
          {task.priority}
        </span>
      </div>
      <h3>{task.title}</h3>
      <p>{task.assignee}</p>
    </article>
  )
}

function Column({ column }) {
  return (
    <section className="board-column">
      <div className="column-header">
        <h2>{column.title}</h2>
        <span>{column.tasks.length}</span>
      </div>
      <div className="task-list">
        {column.tasks.map((task) => (
          <TaskCard key={`${column.title}-${task.title}`} task={task} />
        ))}
      </div>
    </section>
  )
}

export default function App() {
  return (
    <main className="orbit-shell">
      <header className="app-header">
        <div>
          <p className="eyebrow">Sprint 14</p>
          <h1>Orbit</h1>
        </div>
        <button type="button" className="add-task-button">+ Add task</button>
      </header>

      <section className="board" aria-label="Orbit task board">
        {columns.map((column) => (
          <Column key={column.title} column={column} />
        ))}
      </section>
    </main>
  )
}

* {
  box-sizing: border-box;
}

:root {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #172033;
  background: #f5f7fb;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background:
    radial-gradient(circle at top left, rgba(84, 112, 255, 0.14), transparent 32rem),
    linear-gradient(135deg, #fbfcff 0%, #eef3f9 100%);
}

button {
  font: inherit;
}

.orbit-shell {
  width: min(1180px, calc(100% - 40px));
  margin: 0 auto;
  padding: 48px 0;
}

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 30px;
}

.eyebrow {
  margin: 0 0 6px;
  color: #6b7890;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: clamp(42px, 6vw, 68px);
  line-height: 0.95;
  letter-spacing: -0.065em;
  color: #111827;
}

.add-task-button {
  border: 0;
  border-radius: 999px;
  padding: 14px 22px;
  color: #ffffff;
  background: #335cff;
  font-weight: 800;
  box-shadow: 0 14px 28px rgba(51, 92, 255, 0.28);
  cursor: pointer;
  transition: transform 160ms ease, box-shadow 160ms ease;
}

.add-task-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 18px 36px rgba(51, 92, 255, 0.32);
}

.board {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
}

.board-column {
  min-height: 560px;
  padding: 18px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 28px;
  background: rgba(255, 255, 255, 0.78);
  box-shadow: 0 22px 60px rgba(31, 41, 55, 0.08);
  backdrop-filter: blur(18px);
}

.column-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  padding: 4px 4px 0;
}

.column-header h2 {
  margin: 0;
  font-size: 18px;
  color: #243047;
}

.column-header span {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: #eef2ff;
  color: #335cff;
  font-weight: 800;
}

.task-list {
  display: grid;
  gap: 14px;
}

.task-card {
  position: relative;
  overflow: hidden;
  min-height: 154px;
  padding: 18px;
  border: 1px solid #e7edf5;
  border-radius: 22px;
  background: #ffffff;
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.07);
}

.task-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 5px;
  background: linear-gradient(#5271ff, #9aa9ff);
}

.card-topline {
  display: flex;
  justify-content: flex-end;
  margin-bottom: 24px;
}

.priority {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 7px 10px;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.03em;
}

.priority-high {
  color: #b42318;
  background: #fee4e2;
}

.priority-medium {
  color: #b54708;
  background: #fef0c7;
}

.priority-low {
  color: #027a48;
  background: #dcfae6;
}

.task-card h3 {
  margin: 0 0 12px;
  font-size: 19px;
  line-height: 1.25;
  letter-spacing: -0.02em;
  color: #101828;
}

.task-card p {
  margin: 0;
  color: #667085;
  font-weight: 700;
}

@media (max-width: 820px) {
  .orbit-shell {
    width: min(100% - 28px, 680px);
    padding: 28px 0;
  }

  .app-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .board {
    grid-template-columns: 1fr;
  }

  .board-column {
    min-height: auto;
  }
}

