  font-size: clamp(42px, 6vw, 68px);
  line-height: 0.95;
  letter-spacing: -0.065em;
  color: #111827;
}

.add-task-button {
  border: 0;
  border-radius: 999px;
  padding: 14px 22px;
  color: #ffffff;
  background: #335cff;
  font-weight: 800;
  box-shadow: 0 14px 28px rgba(51, 92, 255, 0.28);
  cursor: pointer;
  transition: transform 160ms ease, box-shadow 160ms ease;
}

.add-task-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 18px 36px rgba(51, 92, 255, 0.32);
}

.board {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
}

.board-column {
  min-height: 560px;
  padding: 18px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 28px;
  background: rgba(255, 255, 255, 0.78);
  box-shadow: 0 22px 60px rgba(31, 41, 55, 0.08);
  backdrop-filter: blur(18px);
}

.column-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  padding: 4px 4px 0;
}

.column-header h2 {
  margin: 0;
  font-size: 18px;
  color: #243047;
}

.column-header span {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: #eef2ff;
  color: #335cff;
  font-weight: 800;
}

.task-list {
  display: grid;
  gap: 14px;
}

.task-card {
  position: relative;
  overflow: hidden;
  min-height: 154px;
  padding: 18px;
  border: 1px solid #e7edf5;
  border-radius: 22px;
  background: #ffffff;
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.07);
}

.task-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 5px;
  background: linear-gradient(#5271ff, #9aa9ff);
}

.card-topline {
  display: flex;
  justify-content: flex-end;
  margin-bottom: 24px;
}

.priority {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 7px 10px;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.03em;
}

.priority-high {
  color: #b42318;
  background: #fee4e2;
}

.priority-medium {
  color: #b54708;
  background: #fef0c7;
}

.priority-low {
  color: #027a48;
  background: #dcfae6;
}

.task-card h3 {
  margin: 0 0 12px;
  font-size: 19px;
  line-height: 1.25;
  letter-spacing: -0.02em;
  color: #101828;
}

.task-card p {
  margin: 0;
  color: #667085;
  font-weight: 700;
}

@media (max-width: 820px) {
  .orbit-shell {
    width: min(100% - 28px, 680px);
    padding: 28px 0;
  }

  .app-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .board {
    grid-template-columns: 1fr;
  }

  .board-column {
    min-height: auto;
  }
}

